let palette = [['#FFBA08', '#FFF275'], ['#3F88C5', '#0A369D'], ['#D60B26']]
// let palette = [['#3FDD37', '#09A129'], ['#D0FEF5', '#FAB2EA'], ['#550527']]
let swarms = []

function setup() {
	createCanvas(1280, 720);
	strokeCap(SQUARE)
	strokeWeight(1.5)
	colorMode(RGB, 255, 255, 255, 100)
	background(255)

	let diskSampling = new PoissonDiskSampling({
		shape: [width*1.2, height*1.2],
		minDistance: 15,
		maxDistance: 15,
		tries: 40
	})
	let samplings = diskSampling.fill()

	let flowfields = [new FlowField(), new FlowField(), new FlowField(), new FlowField(), new FlowField()]
	for(let sampling of samplings) {
		let colorFactor = floor(random(2.5))
		let vec = createVector(sampling[0] - width*0.1, sampling[1] - height*0.1)
		swarms.push(new Swarm(vec.x, vec.y, color(random(palette[colorFactor])), flowfields[colorFactor]))
	}
	swarms = shuffle(swarms)
}

function draw() {
	swarms[frameCount].show()
}

function shiftColor(col, range, alf) {
	let shiftRange = range
	let shiftedRed = constrain(red(window.color(col)) + shiftRange[0] + (shiftRange[1] - shiftRange[0]) * (random()), 0, 255)
	let shiftedGreen = constrain(green(window.color(col)) + shiftRange[0] + (shiftRange[1] - shiftRange[0]) * (random()), 0, 255)
	let shiftedBlue = constrain(blue(window.color(col)) + shiftRange[0] + (shiftRange[1] - shiftRange[0]) * (random()), 0, 255)
	return color(shiftedRed, shiftedGreen, shiftedBlue, alf)
}

class Swarm {
	constructor(x, y, col, flowfield) {
		this.center = createVector(x, y)
		this.groupRad = random(10, 17.5)
		this.flowfield = flowfield
		this.density = 0.4
		this.color = col
		this.particles = []
		this.prepare()
	}

	prepare() {
		let numParticles = sq(this.groupRad) * PI * this.density
		for(let i = 0; i < numParticles; i++) {
			let distCenter = this.groupRad * sqrt(random())
			let anglePolar = random(TAU)
			let particlePos = createVector(this.center.x + distCenter * cos(anglePolar), this.center.y + distCenter * sin(anglePolar))
			this.particles.push(new Particle(particlePos, this.color, this.flowfield))
		}
	}

	show() {
		for(let particle of this.particles) {
			particle.show()
		}
	}
}

class Particle {
	constructor(pos, col, flowfield) {
		this.pos = pos
		this.posPrev = this.pos.copy()

		this.lifeSpan = floor(random(10, 110)/2)
		this.color = shiftColor(col, [-5, 5], floor(random(40, 60)))
		this.flowfield = flowfield
	}

	show() {
		stroke(this.color)
		let _wG_1 = 0; while ((this.lifeSpan >= 1) && ++_wG_1 < 20000) {
			this.move()
			this.drawProgress()
		}
	}

	move() {
		this.lifeSpan -= 4
		let moveStep = 4
		this.posPrev = this.pos.copy()

		let moveAng = this.flowfield.getAng(this.pos.x, this.pos.y, 0)
		this.pos = createVector(this.pos.x + moveStep * cos(moveAng), this.pos.y + moveStep * sin(moveAng))
	}

	drawProgress() {
		line(this.pos.x, this.pos.y, this.posPrev.x, this.posPrev.y)
	}
}

class FlowField {
	constructor() {
		this.particularOffset = floor(random(10000))
	}

	getAng(x, y, z) {
		let ang = PI
		ang += PI/3 * (noise(x * 0.001, y * 0.001, z * 0.0005) - 0.5)*2
		ang += PI * getRatio(x, y) * (noise(x * 0.003 + this.particularOffset, y * 0.003 + this.particularOffset, z * 0.003 + this.particularOffset) - 0.5)*2
		return ang
	}
}

function getRatio(x, y) {
	return dist(width, height/2, x, y) / width
}
